/// The fake: every call is recorded by name and answered with the default.
#[derive(Default)]
pub struct FakeAgentApi {
    pub calls: std::sync::Mutex<Vec<String>>,
}

impl FakeAgentApi {
    pub fn calls(&self) -> Vec<String> {
        self.calls.lock().unwrap_or_else(std::sync::PoisonError::into_inner).clone()
    }
    fn note(&self, name: &str) {
        self.calls.lock().unwrap_or_else(std::sync::PoisonError::into_inner).push(name.to_string());
    }
}

